// EnvelopeTest.cpp: proves the Protobuf code generated from matchforge.proto
// works at runtime. It is not enough that the code compiles: the message must
// survive being turned into bytes and back, as it will on the network.
#include <gtest/gtest.h>  // GoogleTest: TEST(), ASSERT_*, EXPECT_*.

#include <cstdint>
#include <string>

#include "matchforge.pb.h"  // Generated by protoc during the build (see proto/CMakeLists.txt).

// Builds an Envelope holding a Heartbeat, turns it into bytes, parses the bytes
// back into a new Envelope, and checks that the same data came out.
TEST(EnvelopeTest, HeartbeatSurvivesSerializeAndParse) {
    // Build the message the way a sender would: set the oneof payload to a Heartbeat.
    matchforge::v1::Envelope sent;
    matchforge::v1::Heartbeat* heartbeat = sent.mutable_heartbeat();
    heartbeat->set_sent_at_unix_ms(1234567890);

    // SerializeToString writes the message into a compact binary form.
    // ASSERT_TRUE stops this test at once if it fails, because later lines depend on it.
    std::string bytes;
    ASSERT_TRUE(sent.SerializeToString(&bytes));
    EXPECT_FALSE(bytes.empty());

    // ParseFromString reads those bytes back into a fresh message, as a receiver would.
    matchforge::v1::Envelope received;
    ASSERT_TRUE(received.ParseFromString(bytes));

    // The oneof must still say "this is a heartbeat", and the timestamp must match.
    EXPECT_EQ(received.payload_case(), matchforge::v1::Envelope::kHeartbeat);
    EXPECT_EQ(received.heartbeat().sent_at_unix_ms(), std::uint64_t{1234567890});
}
